package com.stackvalue;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class StackValuePluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(StackValuePlugin.class);
		RuneLite.main(args);
	}
}

package com.stackvalue;

import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

import java.awt.*;

@ConfigGroup("stackvalue")
public interface StackValueConfig extends Config
{


	@Alpha
	@ConfigItem(keyName = "a-commonItemColor", name = "Common Item Color",
			description = "Color of a Common Item", position = 1)
	default Color getCommonItemColor()
	{
		return new Color(0,0,0,0.0f);
	}
	@ConfigItem(keyName = "a-commonItemValue", name = "Common GE Value",
			description = "Max Value of a Common Item", position = 2)
	default int getCommonItemValue()
	{
		return 1000;
	}

	@Alpha
	@ConfigItem(keyName = "b-uncommonItemColor", name = "Uncommon Item Color",
			description = "Color of a Uncommon Item", position = 3)
	default Color getUncommonItemColor()
	{
		return new Color(0, 240 / 255f, 0, 110 / 255f);
	}
	@ConfigItem(keyName = "b-uncommonItemValue", name = "Uncommon GE Value",
			description = "Max Value of a Uncommon Item", position = 4)
	default int getUncommonItemValue()
	{
		return 12500;
	}

	@Alpha
	@ConfigItem(keyName = "c-rareItemColor", name = "Rare Item Color",
			description = "Color of a Rare Item", position = 5)
	default Color getRareItemColor()
	{
		return new Color(0, 100 / 255f, 240 / 255f, 195 / 255f);
	}

	@ConfigItem(keyName = "c-rareItemValue", name = "Rare GE Value",
			description = "Max Value of a Rare Item", position = 6)
	default int getRareItemValue()
	{
		return 125000;
	}

	@Alpha
	@ConfigItem(keyName = "d-epicItemColor", name = "Epic Item Color",
			description = "Color of a Epic Item", position = 7)
	default Color getEpicItemColor()
	{
		return new Color(160 / 255f, 50 / 255f, 240 / 255f, 195 / 255f);
	}

	@ConfigItem(keyName = "d-epicItemValue", name = "Epic GE Value",
			description = "Max Value of a Epic Item", position = 8)
	default int getEpicItemValue()
	{
		return 1800000;
	}


	@Alpha
	@ConfigItem(keyName = "e-legendaryItemColor", name = "Legendary Item Color",
			description = "Color of a Legendary Item", position = 9)
	default Color getLegendaryItemColor()
	{
		return new Color(255 / 255f, 120 / 255f, 0 / 255f, 195 / 255f);
	}

	@ConfigItem(keyName = "f-showFill", name = "Fill",
			description = "Shade items with their value color, on top of the outline", position = 10)
	default boolean showFill()
	{
		return false;
	}

	@Range(min = 0, max = 255)
	@ConfigItem(keyName = "g-fillOpacity", name = "Fill Opacity",
			description = "How strongly items are shaded. 0 draws no fill; 255 replaces the item's "
					+ "colors entirely, leaving only its shape", position = 11)
	default int getFillOpacity()
	{
		return 128;
	}
}

package com.stackvalue;

import com.google.common.cache.Cache;
import com.google.common.cache.CacheBuilder;
import com.google.inject.Inject;
import lombok.Value;

import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.ImageUtil;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;

public class StackValueOverlay extends WidgetItemOverlay
{
	private final StackValuePlugin plugin;
	private final StackValueConfig config;
	private final ItemManager itemManager;

	/**
	 * Shading an item recolors every pixel of its sprite, which is far too slow to redo each frame
	 * for a full bank. Keyed on color as well as item, so a re-tiered or recolored item misses the
	 * cache and is redrawn rather than served stale.
	 */
	private final Cache<FillKey, Image> fillCache;

	@Inject
	private StackValueOverlay(StackValuePlugin plugin, StackValueConfig config, ItemManager itemManager)
	{
		this.plugin = plugin;
		this.config = config;
		this.itemManager = itemManager;

		showOnEquipment();
		showOnInventory();
		showOnBank();

		fillCache = CacheBuilder.newBuilder()
				.concurrencyLevel(1)
				.maximumSize(256)
				.build();
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem itemWidget)
	{
		final int quantity = itemWidget.getQuantity();
		final Color color = plugin.getValueColor(stackValue(itemId, quantity));

		// A fully transparent tier color is how a tier is hidden, so skip the whole item.
		if (color == null || color.getAlpha() == 0)
		{
			return;
		}

		final Rectangle bounds = itemWidget.getCanvasBounds();
		final int x = (int) bounds.getX();
		final int y = (int) bounds.getY();

		final BufferedImage outline = itemManager.getItemOutline(itemId, quantity, color);
		if (outline != null)
		{
			graphics.drawImage(outline, x, y, null);
		}

		final int opacity = config.getFillOpacity();
		if (!config.showFill() || opacity <= 0)
		{
			return;
		}

		// The slider sets the fill's transparency outright, independent of the tier color's own
		// alpha, so it can run from invisible up to completely replacing the item's colors.
		final Image fill = fill(itemId, quantity, ColorUtil.colorWithAlpha(color, opacity));
		if (fill != null)
		{
			graphics.drawImage(fill, x, y, null);
		}
	}

	/**
	 * Value of a whole stack. Widened to a long because a single stack can exceed the range of an
	 * int, which would wrap negative and drop the item into the lowest tier.
	 */
	private long stackValue(int itemId, int quantity)
	{
		return (long) itemManager.getItemPrice(itemId) * quantity;
	}

	private Image fill(int itemId, int quantity, Color color)
	{
		final FillKey key = new FillKey(itemId, quantity, color.getRGB());

		final Image cached = fillCache.getIfPresent(key);
		if (cached != null)
		{
			return cached;
		}

		final AsyncBufferedImage sprite = itemManager.getImage(itemId, quantity, false);

		// Sprites load in the background and are blank until they arrive. Caching one now would pin
		// an empty fill in place, so draw nothing and let a later frame build it for real.
		if (sprite == null || isBlank(sprite))
		{
			return null;
		}

		final Image fill = ImageUtil.fillImage(sprite, color);
		fillCache.put(key, fill);
		return fill;
	}

	private static boolean isBlank(BufferedImage image)
	{
		for (int x = 0; x < image.getWidth(); x++)
		{
			for (int y = 0; y < image.getHeight(); y++)
			{
				if ((image.getRGB(x, y) >>> 24) != 0)
				{
					return false;
				}
			}
		}

		return true;
	}

	@Value
	private static class FillKey
	{
		int itemId;
		int quantity;
		int rgb;
	}
}

package com.stackvalue;

import com.google.inject.Provides;
import javax.inject.Inject;

import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

import java.awt.Color;

@PluginDescriptor(
		name = "Stack Value"
)
public class StackValuePlugin extends Plugin
{
	@Inject
	private StackValueConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private StackValueOverlay overlay;

	@Override
	protected void startUp() throws Exception
	{
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown() throws Exception
	{
		overlayManager.remove(overlay);
	}

	@Provides
	StackValueConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(StackValueConfig.class);
	}

	Color getValueColor(final long stackValue)
	{
		if (stackValue < config.getCommonItemValue())
		{
			return config.getCommonItemColor();
		}
		else if (stackValue < config.getUncommonItemValue())
		{
			return config.getUncommonItemColor();
		}
		else if (stackValue < config.getRareItemValue())
		{
			return config.getRareItemColor();
		}
		else if (stackValue < config.getEpicItemValue())
		{
			return config.getEpicItemColor();
		}

		return config.getLegendaryItemColor();
	}
}
